CREATE TABLE IF NOT EXISTS catalog_advertisements(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),latest_revision TEXT,published_revision TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS catalog_ad_revisions(id TEXT PRIMARY KEY,ad_id TEXT NOT NULL REFERENCES catalog_advertisements(id),owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),title TEXT NOT NULL,placement TEXT NOT NULL CHECK(placement IN('salon','home','hair','makeup','skin','nails','products','discounts')),media_id TEXT NOT NULL REFERENCES catalog_media(id),budget INTEGER NOT NULL DEFAULT 0 CHECK(budget>=0),active INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL CHECK(status IN('pending','approved','rejected')),reason TEXT NOT NULL DEFAULT '',reviewer TEXT REFERENCES catalog_accounts(id),reviewed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
